import{c as a,Q as t,j as o,m as r}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"How to master Fable 5 (Full Course)","description":"","frontmatter":{"url":"https://x.com/exm7777/status/2072694856795955630","title":"How to master Fable 5 (Full Course)","author":"EXM7777","archived":"2026-07-03T00:00:00.000Z","handle":"@EXM7777","published":"2026-07-02T00:00:00.000Z","stats":"439 likes · 46 retweets · 998 bookmarks · 130425 views","tags":["fable5","tutorial","agent-team","loops","pocock-skills","workflow"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-07-02-@EXM7777-955630.md","filePath":"research/tweets/2026-07-02-@EXM7777-955630.md","lastUpdated":1785909234000}'),l={name:"research/tweets/2026-07-02-@EXM7777-955630.md"};function s(i,e,n,d,c,h){return t(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="how-to-master-fable-5-full-course-—-exm7777" tabindex="-1">How to master Fable 5 (Full Course) — @EXM7777 <a class="header-anchor" href="#how-to-master-fable-5-full-course-—-exm7777" aria-label="Permalink to &quot;How to master Fable 5 (Full Course) — @EXM7777&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/exm7777/status/2072694856795955630" target="_blank" rel="noreferrer">https://x.com/exm7777/status/2072694856795955630</a><strong>作者</strong>：EXM7777（@EXM7777） <strong>發布日期</strong>：2026-07-02 <strong>收錄日期</strong>：2026-07-03 <strong>類型</strong>：Twitter Article <strong>統計</strong>：439 likes · 46 retweets · 998 bookmarks · 130425 views</p><hr><h2 id="全文摘要" tabindex="-1">全文摘要 <a class="header-anchor" href="#全文摘要" aria-label="Permalink to &quot;全文摘要&quot;">​</a></h2><p><strong>定位</strong>：Fable = leader（指揮），Opus/Codex/Sonnet = workers（執行）。</p><h3 id="fable-5-五項能力" tabindex="-1">Fable 5 五項能力 <a class="header-anchor" href="#fable-5-五項能力" aria-label="Permalink to &quot;Fable 5 五項能力&quot;">​</a></h3><ol><li>Never loses the thread（18,000 行代碼遷移 3 小時無人監督完成）</li><li>Sees like a person（最高 computer-use 分數，可從截圖重建頁面）</li><li>Delivers finished work, not answers（raw files → deliverable）</li><li>Gets smarter from files（notes 文件夾 = 跨 run 記憶複利）</li><li>Built to lead（管理 agent team）</li></ol><h3 id="三個-secret" tabindex="-1">三個 Secret <a class="header-anchor" href="#三個-secret" aria-label="Permalink to &quot;三個 Secret&quot;">​</a></h3><ul><li><strong>Secret 1：Don&#39;t overguide</strong>：逐步指令和長規則列表對舊模型是脚手架，對 Fable 是天花板</li><li><strong>Secret 2：Keep CLAUDE.md light</strong>：只包含「它是什麼/關鍵命令/已知錯誤」</li><li><strong>Secret 3：Abuse loops and goals</strong>：<code>/goal</code> + 小型 judge model 每輪驗收 → 自主工作到完成</li></ul><h3 id="workers-設定" tabindex="-1">Workers 設定 <a class="header-anchor" href="#workers-設定" aria-label="Permalink to &quot;Workers 設定&quot;">​</a></h3><p>每個 worker = <code>.claude/agents/</code> 裡一個小文件（name / model / short job description）</p><h3 id="五個高價值-workflow" tabindex="-1">五個高價值 Workflow <a class="header-anchor" href="#五個高價值-workflow" aria-label="Permalink to &quot;五個高價值 Workflow&quot;">​</a></h3><ol><li>Giant codebase job（大型遷移，分段+每段獨立 reviewer）</li><li>Deep research sprints（parallel workers + checker 攻擊每個 claim）</li><li>Orchestrator（未詳述）</li><li>Frontend（未詳述）</li><li>Knowledge base（未詳述）</li></ol><h3 id="一次完整-project-流程-landing-page-示例" tabindex="-1">一次完整 Project 流程（Landing Page 示例） <a class="header-anchor" href="#一次完整-project-流程-landing-page-示例" aria-label="Permalink to &quot;一次完整 Project 流程（Landing Page 示例）&quot;">​</a></h3><ol><li>Brief → 2. Plan（Shift+Tab plan mode + Pocock skills）→ 3. Team 工作（Fable dispatch worker → verifier 冷驗） → 4. /goal 設置 → 5. 早上 review 帶 proof 的 run log</li></ol><p><strong>Pocock skills</strong>：<code>github.com/mattpocock/skills</code>（含 planning skills）</p><h3 id="整體配置一覽" tabindex="-1">整體配置一覽 <a class="header-anchor" href="#整體配置一覽" aria-label="Permalink to &quot;整體配置一覽&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>run Fable as leader: pocock skills for plan, Opus/Codex workers for labor, Fable reviews everything</span></span>
<span class="line"><span>don&#39;t overguide: outcome + constraints + reason, delete scaffolding</span></span>
<span class="line"><span>keep CLAUDE.md light: what it is, commands, known mistakes</span></span>
<span class="line"><span>abuse goals and loops: finish lines with pasted proof and a written brake</span></span>
<span class="line"><span>five workflows: codebase / research / orchestrator / frontend / knowledge base</span></span></code></pre></div><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：Fable 5 入門全課（含宣傳 weeklyaiops.com 社群）：leader/workers 角色分工、三個 secret（不過度引導/輕 CLAUDE.md/善用 /goal loops）、五個 workflow；Pocock skills 是新的外部資源引用。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li>Fable 5 的角色是 leader/orchestrator，不是執行者</li><li>CLAUDE.md light = 只寫「是什麼/命令/已知錯誤」（與 wquguru 的「少寫指令多給意圖」一致）</li><li>plan mode（Shift+Tab）+ Pocock skills 為規劃流程添加結構</li><li>notes 文件夾跨 run 記憶複利（與 wquguru notes/ 系統相同概念）</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>18,000 行代碼遷移 / 3 小時 / 無人監督（未提供驗證）</li><li>Pocock skills：<code>github.com/mattpocock/skills</code></li><li>Judge model checkpoint：每輪工作後自動驗收</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li>內容與已收錄的 wquguru、KSimback、milesdeutscher 高度重疊</li><li>文章含明顯 weeklyaiops.com 社群推廣動機</li><li>「18,000 行 3 小時」claim 無具體驗證，可能是異常最佳情況</li><li>Pocock skills 是值得追蹤的外部資源（未在其他文章中提及）</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>6.5/10</td><td>Pocock skills 和 plan mode 流程有新參考；其他與已收錄文章重疊</td></tr><tr><td>B. 創新性 (20%)</td><td>5.5/10</td><td>三個 secret 都在其他文章已覆蓋；Pocock skills 引用是新資訊</td></tr><tr><td>C. 證據品質 (20%)</td><td>5/10</td><td>18,000 行 claim 無驗證；有推廣動機</td></tr><tr><td>D. 技術深度 (15%)</td><td>6/10</td><td>.claude/agents/ 設定和 /goal judge 機制有適當深度</td></tr><tr><td>E. 泛化性 (15%)</td><td>7/10</td><td>五個 workflow 框架對不同使用場景有價值</td></tr><tr><td><strong>加權總分</strong></td><td><strong>6.0/10</strong></td><td>6.5×0.3+5.5×0.2+5×0.2+6×0.15+7×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Others <strong>理由</strong>：與已收錄文章重疊高；Pocock skills 值得追蹤但不足以單獨整合；有推廣動機降低信息價值。</p>`,31)])])}const k=a(l,[["render",s]]);export{p as __pageData,k as default};
